/* @lc app=leetcode id=2290 lang=kotlin */
class Solution { fun minimumObstacles(grid: Array<IntArray>): Int = grid.size.let { m -> grid[0].size.let { n -> IntArray(m * n) { 1e9.toInt() }.also { dist -> dist[0] = 0 }.let { dist -> java.util.PriorityQueue<IntArray>(compareBy { it[0] }).apply { add(intArrayOf(0, 0, 0)) }.let { pq -> generateSequence { if (pq.isNotEmpty()) pq.poll() else null }.first { curr -> curr[1] == m - 1 && curr[2] == n - 1 || (curr[0] <= dist[curr[1] * n + curr[2]]).let { valid -> if (valid) arrayOf(0 to 1, 1 to 0, 0 to -1, -1 to 0).forEach { (dr, dc) -> (curr[1] + dr).let { nr -> (curr[2] + dc).let { nc -> if (nr in 0 until m && nc in 0 until n) (curr[0] + grid[nr][nc]).let { nd -> if (nd < dist[nr * n + nc]) dist.set(nr * n + nc, nd).also { pq.add(intArrayOf(nd, nr, nc)) } } } } } false } }[0] } } } } }